function sk1130_ai_file(): string {return __DIR__.'/ai_copilot_v1100.php';}
function sk1130_ai_generate(int $bid,int $uid=0): array {
    $b=sk1130_business($bid);
    if(!$b)throw new RuntimeException('Business not found.');
    $fallback=sk1130_fallback_copy($b);
    $result=$fallback;
    $mode='factual';
    $f=sk1130_ai_file();
    if(is_file($f))require_once $f;
    if(function_exists('sk1100ai_settings')&&function_exists('sk1100ai_gemini')){
        try{
            $settings=sk1100ai_settings();
            if(($settings['provider']??'local')==='gemini_ai_studio'&&!empty($settings['api_key_cipher'])){
                $facts="BUSINESS FACTS — use only these facts:\n".json_encode([
                    'name'=>sk1130_business_value($b,['name'],''),
                    'category'=>sk1130_category($b),
                    'description'=>sk1130_business_value($b,['description','tagline'],''),
                    'address'=>sk1130_business_value($b,['address','area'],''),
                    'phone'=>sk1130_business_value($b,['phone'],''),
                    'whatsapp'=>sk1130_business_value($b,['whatsapp'],''),
                    'hours'=>sk1130_business_value($b,['opening_hours','hours','working_hours'],''),
                    'services'=>sk1130_services($b)
                ],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
                $prompt='Create concise website copy as JSON only with keys hero_kicker, hero_headline, hero_subtitle, about_title, about_body, services_intro, why_choose_title, why_choose_points (array), faq (array of objects q,a), meta_title, meta_description. Never invent ratings, prices, availability, awards, opening status, services, history or claims. If a fact is unavailable, omit it. Keep the business name accurate.';
                $raw=sk1100ai_gemini($prompt,'You write grounded business microsite copy for ShahkotPK. Return valid JSON only.',$facts,$settings);
                if(is_string($raw)&&trim($raw)!==''){
                    $raw=trim($raw);
                    $raw=preg_replace('/^```(?:json)?\s*|\s*```$/i','',$raw);
                    $j=json_decode((string)$raw,true);
                    if(is_array($j)){
                        $result=array_merge($fallback,$j);
                        $mode='gemini_ai_studio';
                    }
                }
            }
        }catch(Throwable $e){}
    }
    $result['mode']=$mode;
    $json=json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    $checksum=sk1130_checksum($b);
    if(sk1130_table('business_microsites_v1130')){
        try{
            $q=db()->prepare("INSERT INTO business_microsites_v1130(tenant_id,business_id,enabled,theme_mode,theme_key,layout_variant,ai_enabled,ai_copy_json,source_checksum,last_ai_at,updated_by,created_at,updated_at) VALUES(?,?,1,'auto','auto','auto',1,?,?,NOW(),?,NOW(),NOW()) ON DUPLICATE KEY UPDATE ai_copy_json=VALUES(ai_copy_json),source_checksum=VALUES(source_checksum),last_ai_at=NOW(),updated_by=VALUES(updated_by),updated_at=NOW()");
            $q->execute([sk1130_tid(),$bid,$json,$checksum,$uid?:null]);
        }catch(Throwable $e){}
    }
    return $result;
}
