function sk1130_stats(int $days=30): array {$out=['views'=>0,'contacts'=>0,'ai'=>0,'businesses'=>0];$tid=sk1130_tid();$days=max(1,min(365,$days));try{if(sk1130_table('businesses')){$cols=sk1130_cols('businesses');$w=$tid>0&&in_array('tenant_id',$cols,true)?' WHERE tenant_id='.(int)$tid:'';$out['businesses']=(int)db()->query('SELECT COUNT(*) FROM businesses'.$w)->fetchColumn();}if(sk1130_table('business_microsite_events_v1130')){$q=db()->prepare("SELECT COUNT(*) views,SUM(event_key IN ('call','whatsapp','directions','booking')) contacts,SUM(event_key IN ('ai_open','ai_question')) ai FROM business_microsite_events_v1130 WHERE tenant_id=? AND created_at>=DATE_SUB(NOW(),INTERVAL ".$days." DAY)");$q->execute([$tid]);$r=$q->fetch()?:[];$out['views']=(int)($r['views']??0);$out['contacts']=(int)($r['contacts']??0);$out['ai']=(int)($r['ai']??0);}}catch(Throwable $e){}return $out;}
function sk1130_generate_stale_batch(int $limit=3): array {$s=sk1130_settings();$limit=max(1,min(3,$limit));$done=[];$skipped=[];if(empty($s['enabled'])||empty($s['ai_copy_enabled']))return ['generated'=>[],'skipped'=>['AI copy disabled']];foreach(sk1130_businesses('',100) as $b){if(count($done)>=$limit)break;$bid=(int)$b['id'];$p=sk1130_profile($bid);if(empty($p['enabled'])||empty($p['ai_enabled']))continue;if(trim((string)($p['ai_copy_json']??''))!==''&&!sk1130_source_stale($b,$p))continue;try{$r=sk1130_ai_generate($bid,0);$done[]=['id'=>$bid,'name'=>(string)sk1130_business_value($b,['name'],'Business'),'mode'=>$r['mode']??'factual'];}catch(Throwable $e){$skipped[]='#'.$bid.' '.$e->getMessage();}}return ['generated'=>$done,'skipped'=>$skipped];}
}


